    <button class="trigger-icon" @click="open" aria-label="背包">
      <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">
        <path d="M4 7a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V7z"/>
        <path d="M9 5V3a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2"/><path d="M8 12h8"/>
      </svg>
      <span v-if="count>0" class="trigger-badge">{{ count }}</span>
    </button>
  </div>
</template>
