.trigger-icon{position:fixed;right:14px;top:50%;transform:translateY(-50%);pointer-events:auto;z-index:500;width:44px;height:44px;border-radius:50%;border:1px solid rgba(255,255,255,0.08);background:rgba(8,8,12,0.8);backdrop-filter:blur(12px);color:#fff;display:flex;align-items:center;justify-content:center;cursor:pointer;transition:background .2s}
