<script setup lang="ts">
import { inject, computed } from 'vue';
import host from '@tencent/program-host';

interface BackpackState {
  items: string[];
  questItems: string[];
  showReturnToQuest: boolean;
  currentQuestId: string | null;
}

const state = inject<BackpackState>('backpackState')!;
const count = computed(() => state.items.length);

function close() {
  host.router.back()
}

function resetReturnToQuest() {
  state.showReturnToQuest = false;
  state.currentQuestId = null;
}

function clear() {
  state.items.length = 0;
  host.storage.remove('save');
}

function returnToQuest() {
  if (!state.currentQuestId) return;
  const questId = state.currentQuestId;
  resetReturnToQuest();
  // 隐藏 backpack UI + 恢复 quest UI（跨 program 导航用 close，不弹 backpack 路由栈，下次打开复用 /panel）
  host.navigation.close();
  host.events.emit('questResume', { questId });
}

function isHighlighted(item: string): boolean {
  return state.questItems.includes(item);
}
</script>

<template>
  <div class="panel">
    <header class="panel-header">
      <div class="header-title">
        <h2>背包</h2>
        <span class="count-label">{{ count }}</span>
      </div>
      <button class="icon-btn" @click="close" aria-label="关闭">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M18 6L6 18M6 6l12 12"/></svg>
      </button>
    </header>

    <button v-if="state.showReturnToQuest" class="btn btn-secondary return-btn" @click="returnToQuest">
      <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M19 12H5M12 19l-7-7 7-7"/></svg>
      返回任务
    </button>

    <div class="item-list">
      <div v-for="(item, idx) in state.items" :key="idx" class="item-card" :class="{ 'item-highlight': isHighlighted(item) }">
        <span class="item-name">{{ item }}</span>
        <svg v-if="isHighlighted(item)" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6L9 17l-5-5"/></svg>
      </div>
      <div v-if="count === 0" class="empty-state">
        <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" style="opacity:0.3"><path d="M4 7a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V7z"/><path d="M9 5V3a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2"/></svg>
        <p>背包空空如也</p>
      </div>
    </div>

    <footer class="panel-footer">
      <button class="btn btn-danger-outline" @click="clear">清空</button>
      <button class="btn btn-secondary" @click="close">关闭</button>
    </footer>
  </div>
</template>

<style>
