import { createApp, reactive, type App as VueApp } from 'vue';
import host from '@tencent/program-host';
import type { IProgram } from '@tencent/program-host';
import { DEFAULT_ITEMS, type ItemData } from './item-config';
import { createPickupManager, type PickupManager } from './pickup-logic';
import BackpackTrigger from './BackpackTrigger.vue';
import App from './App.vue';

let triggerApp: VueApp | null = null;
let panelApp: VueApp | null = null;
let pickupRef: PickupManager | null = null;
let unsubItemsWatch: (() => void) | null = null;

interface BackpackSaveData { version: 1; items: string[]; pickedUp: string[]; }

const STORAGE_KEY = 'save';
const SAVE_VERSION = 1;

const backpack: IProgram = {
  init(): void {
    const items: ItemData[] = [...DEFAULT_ITEMS];
    const pickedUp = new Set<string>();
    const pickup = createPickupManager();
    pickupRef = pickup;

    const state = reactive({
      items: [] as string[],
      questItems: [] as string[],
      showReturnToQuest: false,
      currentQuestId: null as string | null,
    });

    function restoreSave(): void {
      try {
        const raw = host.storage.get<BackpackSaveData>(STORAGE_KEY);
        if (!raw || raw.version !== SAVE_VERSION) return;
        for (const id of raw.pickedUp) pickedUp.add(id);
        state.items.push(...raw.items);
        host.state.set('items', [...state.items]);
        console.log(`[backpack] 存档已恢复: ${raw.pickedUp.length} 已拾取, ${raw.items.length} 背包物品`);
      } catch (err) { console.warn('[backpack] 恢复存档失败:', err); }
    }

    function saveProgress(): void {
      host.storage.set(STORAGE_KEY, { version: SAVE_VERSION, items: [...state.items], pickedUp: [...pickedUp] });
    }

    restoreSave();

    unsubItemsWatch = host.state.watch('items', (value: unknown) => {
      const arr = value as string[];
      state.items.length = 0;
      state.items.push(...arr);
    });

    for (const item of items) {
      if (pickedUp.has(item.id)) continue;
      try {
        item.objectId = host.sdk.scene.addObject(item.model, item.position);
        console.log(`[backpack] 放置物品: ${item.id} @ ${item.position}`);
      } catch (err) { console.error(`[backpack] 放置物品失败 ${item.id}:`, err); }
    }

    // ---- 路由表 ----
    host.router.routes([
      {
        path: '/',
        component: {
          mount(root: HTMLElement): void {
            root.style.pointerEvents = 'none';
            triggerApp = createApp(BackpackTrigger);
            triggerApp.provide('backpackState', state);
            triggerApp.mount(root);
          },
          onUnmount(): void { triggerApp?.unmount(); triggerApp = null; },
        },
      },
      {
        path: '/panel',
        component: {
          mount(root: HTMLElement, params): void {
            root.style.pointerEvents = 'none';
            if (params.query.from === 'quest') {
              state.showReturnToQuest = true;
              state.currentQuestId = (params.query.questId as string) ?? null;
              if (params.query.highlight) state.questItems = params.query.highlight as string[];
            } else {
              state.showReturnToQuest = false;
              state.currentQuestId = null;
            }
            panelApp = createApp(App);
            panelApp.provide('backpackState', state);
            panelApp.mount(root);
          },
          onUnmount(): void { panelApp?.unmount(); panelApp = null; },
        },
      },
    ]);

    // ---- 拾取逻辑 ----
    pickup.start(items, pickedUp, async (itemId: string) => {
      state.items.push(itemId);
      host.state.set('items', [...state.items]);
      saveProgress();
      try { await host.program('quest').call('onItemCollected', itemId); } catch (err) { console.warn('[backpack] 通知 quest 失败:', err); }
      host.program('official').call('showToast', `拾取: ${itemId}`).catch(() => {});
    });

    // ---- exposedApi ----
    host.registerApi({
      /**
       * v4.1.0：配置驱动路由入口。dispatch 会把 `(zoneName, zone, phase)` 透传给本方法
       * （phase ∈ 'enter' | 'leave' | 'confirm'）。此处**只打印不分支**——用于验证
       * 「路由是否到达 program」，不区分通道语义（出圈同样进面板）。
       */
      open: (zoneName?: string, _zone?: unknown, phase?: string) => {
        console.log(
          `[backpack] open 被调用 — zone=${zoneName ?? '(none)'} phase=${phase ?? '(none)'}`,
        );
        void host.router.push('/panel');
      },
      add: (itemId: string, count = 1) => {
        for (let i = 0; i < count; i++) state.items.push(itemId);
        host.state.set('items', [...state.items]);
        saveProgress();
      },
      list: () => [...state.items],
      has: (itemId: string) => state.items.includes(itemId),
      markQuestItems: (requiredItems: string[]) => {
        state.questItems = requiredItems;
        state.showReturnToQuest = true;
        console.log(`[backpack] 标记任务物品: ${requiredItems}`);
      },
    });

    console.log('[backpack] 背包已就绪 (路由化 v4)');
  },

  dispose(): void {
    unsubItemsWatch?.(); unsubItemsWatch = null;
    triggerApp?.unmount(); triggerApp = null;
    panelApp?.unmount(); panelApp = null;
    pickupRef?.stop(); pickupRef = null;
    console.log('[backpack] 背包已卸载');
  },
};

export default backpack;
