import host from '@tencent/program-host';
import type { ItemData } from './item-config';

/** 拾取逻辑管理器 */
export interface PickupManager {
  /**
   * 启动拾取检测（setInterval 100ms）
   * @param pickedUp - 已从场景移除的物品 ID 集合（独立于背包内容，清空背包不会重置）
   */
  start(
    items: ItemData[],
    pickedUp: Set<string>,
    onPickup: (itemId: string) => void,
  ): void;
  /** 停止检测 */
  stop(): void;
}

/** 拾取距离阈值（米） */
const PICKUP_DISTANCE = 1.5;

/**
 * 创建拾取管理器
 * 职责：setInterval 距离检测 + keydown E 键监听 + 头顶提示 DOM
 */
export function createPickupManager(): PickupManager {
  let pickupInterval = 0;
  let pickupHint: HTMLElement | null = null;
  let handleKeyDown: ((e: KeyboardEvent) => void) | null = null;

  function showHint(text: string): void {
    if (pickupHint) return;
    pickupHint = document.createElement('div');
    pickupHint.textContent = text;
    pickupHint.style.cssText =
      'position:fixed;top:40%;left:50%;transform:translateX(-50%);' +
      'pointer-events:none;z-index:300;' +
      'background:rgba(0,0,0,0.7);color:#fff;' +
      'padding:8px 16px;border-radius:6px;font-size:14px;';
    document.body.appendChild(pickupHint);
  }

  function hideHint(): void {
    if (pickupHint) {
      pickupHint.remove();
      pickupHint = null;
    }
  }

  return {
    start(items, pickedUp, onPickup) {
      // —— 100ms 距离检测 ——
      pickupInterval = window.setInterval(() => {
        const pos = host.sdk.character.getPosition();
        if (!pos) {
          hideHint();
          return;
        }

        for (const item of items) {
          if (pickedUp.has(item.id)) continue;

          const dx = pos.x - item.position[0];
          const dy = pos.y - item.position[1];
          const dz = pos.z - item.position[2];
          const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);

          if (dist < PICKUP_DISTANCE) {
            showHint('按 E 拾取');
            return;
          }
        }
        hideHint();
      }, 100);

      // —— E 键拾取 ——
      handleKeyDown = (e: KeyboardEvent) => {
        if (e.key !== 'e' && e.key !== 'E') return;
        const pos = host.sdk.character.getPosition();
        if (!pos) return;

        for (const item of items) {
          if (pickedUp.has(item.id)) continue;
          const dx = pos.x - item.position[0];
          const dy = pos.y - item.position[1];
          const dz = pos.z - item.position[2];
          if (Math.sqrt(dx * dx + dy * dy + dz * dz) < PICKUP_DISTANCE) {
            pickedUp.add(item.id);
            onPickup(item.id);
            if (item.objectId) host.sdk.scene.removeObject(item.objectId);
            hideHint();
            break;
          }
        }
      };
      window.addEventListener('keydown', handleKeyDown);
    },

    stop() {
      clearInterval(pickupInterval);
      if (handleKeyDown) window.removeEventListener('keydown', handleKeyDown);
      hideHint();
    },
  };
}
